-- Q01 전 계층 테이블 목록·행수
SELECT table_schema, table_name, table_type, row_count, last_altered FROM GN_DW.INFORMATION_SCHEMA.TABLES WHERE table_schema IN ('BRONZE_CRM','BRONZE_AGENCY','BRONZE_ERP','BRONZE_BIGQUERY','BRONZE_GA4','BRONZE_GSC','SILVER','GOLD','SERVING') ORDER BY 1, 2;
-- Q02 census 대상 컬럼 목록·타입
SELECT table_schema, table_name, column_name, data_type, ordinal_position FROM GN_DW.INFORMATION_SCHEMA.COLUMNS WHERE table_schema IN ('GOLD','SILVER','SERVING') ORDER BY 1, 2, 5;
-- Q03 census GOLD.DIM_AD_CREATIVE
WITH a AS (SELECT COUNT(*) AS R, COUNT("AD_CREATIVE_SK") AS NN1, COUNT_IF("AD_CREATIVE_SK" <> 0) AS NZ1, APPROX_COUNT_DISTINCT("AD_CREATIVE_SK") AS DC1, COUNT("AD_CREATIVE_BK") AS NN2, COUNT_IF("AD_CREATIVE_BK" IS NOT NULL AND "AD_CREATIVE_BK" <> '') AS NZ2, APPROX_COUNT_DISTINCT("AD_CREATIVE_BK") AS DC2, COUNT("MEDIA_NAME") AS NN3, COUNT_IF("MEDIA_NAME" IS NOT NULL AND "MEDIA_NAME" <> '') AS NZ3, APPROX_COUNT_DISTINCT("MEDIA_NAME") AS DC3, COUNT("PLATFORM") AS NN4, COUNT_IF("PLATFORM" IS NOT NULL AND "PLATFORM" <> '') AS NZ4, APPROX_COUNT_DISTINCT("PLATFORM") AS DC4, COUNT("PLATFORM_TYPE") AS NN5, COUNT_IF("PLATFORM_TYPE" IS NOT NULL AND "PLATFORM_TYPE" <> '') AS NZ5, APPROX_COUNT_DISTINCT("PLATFORM_TYPE") AS DC5, COUNT("CREATIVE") AS NN6, COUNT_IF("CREATIVE" IS NOT NULL AND "CREATIVE" <> '') AS NZ6, APPROX_COUNT_DISTINCT("CREATIVE") AS DC6, COUNT("CM_POSITION") AS NN7, COUNT_IF("CM_POSITION" IS NOT NULL AND "CM_POSITION" <> '') AS NZ7, APPROX_COUNT_DISTINCT("CM_POSITION") AS DC7, COUNT("AD_TYPE") AS NN8, COUNT_IF("AD_TYPE" IS NOT NULL AND "AD_TYPE" <> '') AS NZ8, APPROX_COUNT_DISTINCT("AD_TYPE") AS DC8, COUNT("TARGET_GROUP") AS NN9, COUNT_IF("TARGET_GROUP" IS NOT NULL AND "TARGET_GROUP" <> '') AS NZ9, APPROX_COUNT_DISTINCT("TARGET_GROUP") AS DC9, COUNT("DW_SOURCE_SYSTEM") AS NN10, COUNT_IF("DW_SOURCE_SYSTEM" IS NOT NULL AND "DW_SOURCE_SYSTEM" <> '') AS NZ10, APPROX_COUNT_DISTINCT("DW_SOURCE_SYSTEM") AS DC10, COUNT("DW_LOAD_TS") AS NN11, COUNT("DW_LOAD_TS") AS NZ11, APPROX_COUNT_DISTINCT("DW_LOAD_TS") AS DC11, COUNT("DW_UPDATE_TS") AS NN12, COUNT("DW_UPDATE_TS") AS NZ12, APPROX_COUNT_DISTINCT("DW_UPDATE_TS") AS DC12, COUNT("DW_BATCH_ID") AS NN13, COUNT_IF("DW_BATCH_ID" IS NOT NULL AND "DW_BATCH_ID" <> '') AS NZ13, APPROX_COUNT_DISTINCT("DW_BATCH_ID") AS DC13 FROM GN_DW.GOLD."DIM_AD_CREATIVE")
SELECT 'GOLD' AS TABLE_SCHEMA, 'DIM_AD_CREATIVE' AS TABLE_NAME, a.R AS ROWS_, f.key AS COLUMN_NAME,
       f.value[0]::NUMBER AS NONNULL, f.value[1]::NUMBER AS NONZERO, f.value[2]::NUMBER AS NDV
FROM a, LATERAL FLATTEN(INPUT => OBJECT_CONSTRUCT_KEEP_NULL('AD_CREATIVE_SK', ARRAY_CONSTRUCT(NN1, NZ1, DC1), 'AD_CREATIVE_BK', ARRAY_CONSTRUCT(NN2, NZ2, DC2), 'MEDIA_NAME', ARRAY_CONSTRUCT(NN3, NZ3, DC3), 'PLATFORM', ARRAY_CONSTRUCT(NN4, NZ4, DC4), 'PLATFORM_TYPE', ARRAY_CONSTRUCT(NN5, NZ5, DC5), 'CREATIVE', ARRAY_CONSTRUCT(NN6, NZ6, DC6), 'CM_POSITION', ARRAY_CONSTRUCT(NN7, NZ7, DC7), 'AD_TYPE', ARRAY_CONSTRUCT(NN8, NZ8, DC8), 'TARGET_GROUP', ARRAY_CONSTRUCT(NN9, NZ9, DC9), 'DW_SOURCE_SYSTEM', ARRAY_CONSTRUCT(NN10, NZ10, DC10), 'DW_LOAD_TS', ARRAY_CONSTRUCT(NN11, NZ11, DC11), 'DW_UPDATE_TS', ARRAY_CONSTRUCT(NN12, NZ12, DC12), 'DW_BATCH_ID', ARRAY_CONSTRUCT(NN13, NZ13, DC13))) f ORDER BY f.index;
